### `terragrunt.hcl` Structure Template

```hcl
# iac/terraform/deployments/aws/<env>/terragrunt.hcl

include "common" {
  path   = find_in_parent_folders("common-includes.hcl")
  expose = true
}

include "security_groups" {
  path   = find_in_parent_folders("security-groups.hcl")
  expose = true
}

include "security_group_rules" {
  path = find_in_parent_folders("security-group-rules.hcl")
}

terraform {
  source = "git::ssh://git@github.com/mygainwell/pfe-iac-modules.git//modules/aws/<formation>?ref=<semver-tag>"
}

inputs = {
  product_abr  = include.common.locals.product_abr
  environment  = include.common.locals.environment
  region       = include.common.locals.region

  # Formation-specific inputs sourced from remote state — never hardcoded
  vpc_id          = include.common.dependency.platform.outputs.vpc_id
  private_subnets = include.common.dependency.platform.outputs.private_subnet_ids

  # Security group IDs from security-groups.hcl
  app_sg_id = include.security_groups.locals.app_sg_id
}
```

