### `common-includes.hcl` Structure Template

```hcl
# iac/terraform/deployments/aws/<env>/common-includes.hcl

locals {
  product_abr = get_env("PRODUCT_ABR")            # Set by CD pipeline from .project.yml
  environment = basename(get_terragrunt_dir())     # Derived from directory name — never hardcoded
  region      = get_env("TG_REGION_CONTEXT")       # Set by CD pipeline; fails if unset
}

remote_state {
  backend = "s3"
  generate = {
    path      = "backend.tf"
    if_exists = "overwrite_terragrunt"
  }
  config = {
    bucket         = get_env("TG_STATE_BUCKET")
    key            = "${local.product_abr}/${local.environment}/${local.region}/terraform.tfstate"
    region         = local.region
    encrypt        = true
    dynamodb_table = get_env("TG_STATE_LOCK_TABLE")
  }
}

dependency "platform" {
  config_path = "../../../platform-state/${local.environment}"
  mock_outputs = {
    vpc_id             = "vpc-00000000000000000"
    private_subnet_ids = ["subnet-00000000000000001", "subnet-00000000000000002"]
  }
  mock_outputs_allowed_terraform_commands = ["validate", "plan"]
}
```

